	/* @Test */
	public void testCaptureCopySpecialAgain() {
		long start = 0x406604;
		long end = 0x40660d;
		makeSelection(start, end);
		copySpecialLabelsAndComments();
		waitForSwing();

		showCopyMenu();
		captureMenu();
		cropCopyMenu();
		Image menuImage = image;

		captureListingCallMnemonic(start, end);

